/* ============================================================
   sim-detail-data.js — fine-grained simulation results for the
   leaderboard's "By task" board. Generated by
   scripts/generate_sim_detail.py from
   assets/leaderboard/all_master_records.csv + all_summary.json.

   Regimes
     seen — Seen tasks (5 seen tasks, each at L0-L3).
     zs   — Zero-shot on the 5 unseen tasks (no fine-tuning).
     pft  — Pretrain + fine-tune on the 5 unseen tasks.
     scr  — From scratch on the 5 unseen tasks. THREE-block
            per-scale data is deliberately NOT provided: scratch is a
            single-flavour result, given here per (task, level) cell as
            the MIN over the scales present, which reproduces
            all_summary.json's unseen_scratch_flat overall / by_level
            exactly.

   seen/zs/pft are keyed by pretraining corpus scale — "15", "30",
   "45" — plus a "mean" block (per (task, level) cell averaged over
   the three scales). Value encoding: {model: [SR, SubSR]} in [0,1];
   null where a model has no evaluation for that cell.
   ============================================================ */
